package org.eclipse.rdf4j.sail.nativerdf.wal;

import static org.assertj.core.api.Assertions.assertThat;

import java.io.BufferedOutputStream;
import java.io.IOException;
import java.io.OutputStream;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.zip.CRC32C;

import org.eclipse.rdf4j.model.IRI;
import org.eclipse.rdf4j.model.Literal;
import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.sail.nativerdf.ValueStore;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

class ValueStoreWalStreamingRecoveryTest {

	@TempDir
	Path directory;

	@Test
	void recoversShuffledIdsAndKeepsFirstDuplicate() throws Exception {
		Path values = Files.createDirectories(directory.resolve("values"));
		ValueStoreWalConfig config = writeWal(
				mint(1, 3, "B", "first-three", ""),
				mint(2, 1, "B", "one", ""),
				mint(3, 3, "B", "conflicting-three", ""),
				mint(4, 2, "B", "two", ""));
		try (ValueStoreWAL wal = ValueStoreWAL.open(config);
				ValueStore store = openStore(values, wal)) {
			assertThat(store.getValue(1).stringValue()).isEqualTo("one");
			assertThat(store.getValue(2).stringValue()).isEqualTo("two");
			assertThat(store.getValue(3).stringValue()).isEqualTo("first-three");
			assertThat(store.getID(SimpleValueFactory.getInstance().createBNode("conflicting-three"))).isEqualTo(-1);
			assertThat(store.storeValue(SimpleValueFactory.getInstance().createBNode("four"))).isEqualTo(4);
		}
	}

	@Test
	void recoversNamespaceAndDatatypeBeforeDependentLiteral() throws Exception {
		Path values = Files.createDirectories(directory.resolve("values"));
		String namespace = "http://example.org/";
		String datatype = namespace + "datatype";
		ValueStoreWalConfig config = writeWal(
				mint(1, 3, "L", "typed-value", datatype),
				mint(2, 2, "I", datatype, ""),
				mint(3, 4, "B", "four", ""),
				mint(4, 1, "N", namespace, ""));
		try (ValueStoreWAL wal = ValueStoreWAL.open(config);
				ValueStore store = openStore(values, wal)) {
			IRI datatypeIri = SimpleValueFactory.getInstance().createIRI(datatype);
			assertThat(store.getID(datatypeIri)).isEqualTo(2);
			Literal literal = (Literal) store.getValue(3);
			assertThat(literal.getLabel()).isEqualTo("typed-value");
			assertThat(literal.getDatatype()).isEqualTo(datatypeIri);
			assertThat(store.getID(SimpleValueFactory.getInstance().createLiteral("typed-value", datatypeIri)))
					.isEqualTo(3);
			assertThat(store.getValue(4).stringValue()).isEqualTo("four");
			assertThat(store.storeValue(SimpleValueFactory.getInstance().createIRI(namespace + "new"))).isEqualTo(5);
		}
	}

	@Test
	void skipsGappedWalWithoutClearingExistingValues() throws Exception {
		Path values = Files.createDirectories(directory.resolve("values"));
		try (ValueStore store = new ValueStore(values.toFile())) {
			assertThat(store.storeValue(SimpleValueFactory.getInstance().createBNode("existing"))).isEqualTo(1);
			store.sync();
		}
		ValueStoreWalConfig config = writeWal(
				mint(1, 1, "B", "replacement", ""),
				mint(2, 3, "B", "three-after-gap", ""));
		try (ValueStoreWAL wal = ValueStoreWAL.open(config);
				ValueStore store = openStore(values, wal)) {
			assertThat(store.getValue(1).stringValue()).isEqualTo("existing");
			assertThat(store.getID(SimpleValueFactory.getInstance().createBNode("replacement"))).isEqualTo(-1);
			assertThat(store.storeValue(SimpleValueFactory.getInstance().createBNode("second"))).isEqualTo(2);
		}
	}

	private ValueStoreWalConfig writeWal(String... records) throws IOException {
		Path walDirectory = Files.createDirectories(directory.resolve("wal"));
		try (OutputStream output = new BufferedOutputStream(Files.newOutputStream(walDirectory.resolve("wal-1.v1")))) {
			writeFrame(output, "{\"t\":\"V\",\"ver\":1,\"store\":\"streaming-recovery-test\","
					+ "\"engine\":\"valuestore\",\"created\":0,\"segment\":1,\"firstId\":1}\n");
			for (String record : records) {
				writeFrame(output, record);
			}
		}
		return ValueStoreWalConfig.builder()
				.walDirectory(walDirectory)
				.storeUuid("streaming-recovery-test")
				.recoverValueStoreOnOpen(true)
				.build();
	}

	private static ValueStore openStore(Path values, ValueStoreWAL wal) throws IOException {
		return new ValueStore(values.toFile(), false, ValueStore.VALUE_CACHE_SIZE, ValueStore.VALUE_ID_CACHE_SIZE,
				ValueStore.NAMESPACE_CACHE_SIZE, ValueStore.NAMESPACE_ID_CACHE_SIZE, wal);
	}

	private static String mint(long lsn, int id, String kind, String lexical, String datatype) {
		return "{\"t\":\"M\",\"lsn\":" + lsn + ",\"id\":" + id + ",\"vk\":\"" + kind
				+ "\",\"lex\":\"" + lexical + "\",\"dt\":\"" + datatype + "\",\"lang\":\"\",\"hash\":0}\n";
	}

	private static void writeFrame(OutputStream output, String json) throws IOException {
		byte[] bytes = json.getBytes(StandardCharsets.UTF_8);
		CRC32C crc = new CRC32C();
		crc.update(bytes, 0, bytes.length);
		writeIntLE(output, bytes.length);
		output.write(bytes);
		writeIntLE(output, (int) crc.getValue());
	}

	private static void writeIntLE(OutputStream output, int value) throws IOException {
		output.write(value);
		output.write(value >>> 8);
		output.write(value >>> 16);
		output.write(value >>> 24);
	}
}
